**Aplikácia**

V súbore `app.js` budeme definovať našu aplikáciu.
```javascript
const express = require('express');
const app = express();
const sp4InfoRoutes = require('./routes/sp4InfoRoutes');
const clenoviaTymuRoutes = require('./routes/clenoviaTymuRoutes');

app.use(express.json());
app.use('/sp4-info', sp4InfoRoutes);
app.use('/clenovia-tymu', clenoviaTymuRoutes);

app.listen(3000, () => {
  console.log('Aplikácia beží na porte 3000');
});
```
